import{_ as t,c as a,o as r,aj as i}from"./chunks/framework.CDhdelVI.js";const u=JSON.parse(`{"title":"Convert Recipes with the Calculator","description":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator.","frontmatter":{"title":"Convert Recipes with the Calculator","description":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator.","head":[["meta",{"name":"description","content":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator."}],["meta",{"property":"og:title","content":"Convert Recipes with the Calculator"}],["meta",{"property":"og:description","content":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/guides/calculator-for-recipes.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Convert Recipes with the Calculator"}],["meta",{"name":"twitter:description","content":"Turn a written recipe into baker's percentages, then scale it up or down in the KitchenRatio calculator."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/guides/calculator-for-recipes.html"}]]},"headers":[],"relativePath":"guides/calculator-for-recipes.md","filePath":"guides/calculator-for-recipes.md"}`),n={name:"guides/calculator-for-recipes.md"};function o(s,e,l,c,h,d){return r(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="convert-recipes-with-the-calculator" tabindex="-1">Convert Recipes with the Calculator <a class="header-anchor" href="#convert-recipes-with-the-calculator" aria-label="Permalink to “Convert Recipes with the Calculator”">​</a></h1><p>Turn any written recipe into baker&#39;s percentages, then scale it cleanly. Think of this as reverse-engineering a dough: grams in, ratios out, repeatable forever.</p><div class="guide-glance"><div class="guide-glance-card"><strong>Best For</strong><span>Translating existing recipes into a ratio-based formula you can reuse.</span></div><div class="guide-glance-card"><strong>Focus</strong><span>Setting flour as the baseline, matching grams, and capturing percentages.</span></div><div class="guide-glance-card"><strong>Read This Next</strong><span>Pair with baker&#39;s percentage and the main calculator guide.</span></div></div><h2 id="step-1-set-the-flour-baseline" tabindex="-1">Step 1: Set the Flour Baseline <a class="header-anchor" href="#step-1-set-the-flour-baseline" aria-label="Permalink to “Step 1: Set the Flour Baseline”">​</a></h2><p>Put your recipe&#39;s flour weight into the calculator so that number becomes your 100%. The cleanest way is to switch <strong>Batch size</strong> to <strong>Flour</strong> and enter the flour grams there, or click the flour weight and type directly.</p><h2 id="step-2-match-ingredients-by-grams" tabindex="-1">Step 2: Match Ingredients by Grams <a class="header-anchor" href="#step-2-match-ingredients-by-grams" aria-label="Permalink to “Step 2: Match Ingredients by Grams”">​</a></h2><p>Add the ingredients you need (water, salt, yeast, enrichments).<br> Click either the <strong>g</strong> or <strong>%</strong> value and type directly, or use the slider if that is faster for you.<br> The calculator keeps both values in sync as you dial the formula in.</p><h2 id="step-3-capture-the-ratio" tabindex="-1">Step 3: Capture the Ratio <a class="header-anchor" href="#step-3-capture-the-ratio" aria-label="Permalink to “Step 3: Capture the Ratio”">​</a></h2><p>Once the grams and percentages match your source recipe, the converted formula is set.<br> If you want to keep that converted formula, open <strong>Recipe</strong> and use <strong>Share</strong> to copy a link with the current settings.<br> You can still write the percentages down, but the shared link is the quickest way to save or send the result.</p><h2 id="step-4-scale-the-batch" tabindex="-1">Step 4: Scale the Batch <a class="header-anchor" href="#step-4-scale-the-batch" aria-label="Permalink to “Step 4: Scale the Batch”">​</a></h2><p>Keep the percentages fixed and change the batch target.<br> You can scale by flour weight, target total dough, or portions, and every ingredient updates automatically.</p><h2 id="example-workflow" tabindex="-1">Example Workflow <a class="header-anchor" href="#example-workflow" aria-label="Permalink to “Example Workflow”">​</a></h2><ol><li>Flour is 500g, so set Flour to 500g.</li><li>Water is 325g, so enter 325g or 65% for water.</li><li>Salt is 10g, so enter 10g or 2% for salt.</li><li>Yeast is 2.5g, so enter 2.5g or 0.5% for yeast.</li><li>Increase flour to 800g to scale the entire recipe.</li></ol><h2 id="practical-tips" tabindex="-1">Practical Tips <a class="header-anchor" href="#practical-tips" aria-label="Permalink to “Practical Tips”">​</a></h2><ul><li>Weigh everything in grams. Volumes lie.</li><li>If your recipe has oil, sugar, eggs, or dairy, add them with Add Ingredient.</li><li>Type directly into the <code>g</code> or <code>%</code> values when you already know the target number.</li><li>If the recipe uses tangzhong, yudane, poolish, or biga, add those in <strong>Preferments &amp; Scalds</strong> so the formula stays true to the original process.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><div class="content-section"><ul><li><a href="/guides/kitchenratio-calculator.html">KitchenRatio Calculator</a></li><li><a href="/guides/bakers-percentage.html">Baker&#39;s Percentage</a></li><li><a href="/guides/hydration.html">Hydration</a></li></ul></div><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><div class="content-section"><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul></div>',19)])])}const g=t(n,[["render",o]]);export{u as __pageData,g as default};
